-- +goose Up
-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.70.0',
  '2026-08-05',
  'Своя почта на resager.ru: приём писем прямо в приложение + страница «Почта»',
  E'На resager.ru заработала своя почта — приём писем прямо в приложение. Ящиков и почтового клиента нет: письма приходят на страницу «Почта», где их можно читать, искать и разбирать.\n\nАдреса заводятся вручную, и это главный фильтр от спама: всё, что приходит на незаведённый адрес, отбивается ещё до приёма и в базу не попадает вообще. Для каждого магазина можно завести одноразовый алиас (например ozon-a7f3@resager.ru) и потребовать, чтобы письма шли только с домена этого магазина — тогда сразу видно, кто продал адрес, и алиас выключается одной кнопкой.\n\nПисьма проверяются на подозрительность (SPF, обратная запись адреса, признаки рассылки скриптом); набравшие много очков уезжают во вкладку «Спам», но не удаляются. HTML письма показывается в песочнице: скрипты не выполняются, а картинки не загружаются, пока не нажмёшь «показать картинки» — в рассылках они работают маячками и сообщают отправителю, что письмо открыли.\n\nВкладка «Защита» показывает, кто ломился на почтовый порт. Боты закрываются автоматически: за перебор адресов, поток ошибок или разговор до приветствия — сначала на час, при повторах дольше. Разблокировать можно вручную.\n\nО новом письме бот пишет в Telegram (спам не тревожит).',
  E'Свой приёмник (receive-only SMTP) в internal/smtpd, ~700 строк на stdlib: net/textproto даёт DotReader с корректным снятием точечного экранирования — единственное по-настоящему хитрое место протокола. Postfix+Dovecot отвергнуты сознательно: 1–1.5 ГБ из 2.3 свободных и несопоставимая поверхность атаки ради задачи «читать письма приложением».\n\nПорядок защиты (от дешёвого к дорогому): блокировка IP по памяти → пауза 1.5 с перед баннером и разрыв, если клиент заговорил первым (боты так делают, законные серверы — нет) → лимит подключений и писем на IP в час → SIZE в MAIL FROM → отказ отправителю с нерезолвимым доменом → RCPT TO по белому списку (главный барьер: словарный перебор не доходит до DATA) → only_from у алиаса → лимит на письмо 15 МБ. Ретрансляции нет ни при каких условиях, AUTH отвечает 502 намеренно, VRFY — 252 (подтверждать адреса значит помогать перебору).\n\nСпам-оценка (порог 6, письмо помечается, но НЕ удаляется): нет PTR / FCrDNS не сходится, HELO без домена или выдающий себя за нас, отсутствие Message-ID и Date, отсутствие TLS, SPF. SPF реализован упрощённо (ip4/ip6/a/mx/include/all, лимит 10 запросов, глубина 3) и используется ТОЛЬКО для оценки: отклонять по нему нельзя — законные пересылки ломают SPF штатно.\n\nSTARTTLS с самоподписанным сертификатом (хранится в DATA_DIR, не перевыпускается на каждый старт): для входящей почты применяется оппортунистический TLS (RFC 7435), сертификат отправители не проверяют. MAIL_TLS_CERT/KEY подменяют его настоящим.\n\nРазбор MIME — stdlib плюс x/text для перекодировки (windows-1251 и koi8-r в русских магазинах живее всех живых); x/text уже был в зависимостях транзитом. Исходник письма кладётся на диск, тела в базу с обрезкой — разбор можно повторить новым кодом. HTML в интерфейсе рендерится в iframe sandbox="" с CSP default-src none; проверено: скрипт из письма не выполняется, запрос к трекеру не уходит, contentDocument недоступен.\n\nМиграция 0087: mail_addresses, mail_messages, mail_attachments, mail_ip_stats (счётчики по IP, а не журнал событий — порт 25 перебирают круглосуточно) + user_settings.mail_notify. В docker-compose появился единственный публикуемый порт стека 25:2525 (контейнер работает не от root и привилегированный порт занять не может).\n\nПоймано при проверке: «разблокировать» чистило только базу, а приёмник держит блокировки в памяти — адрес оставался бы закрыт до перезапуска; добавлен limiter.Unblock и проброс smtpd.Server.Unblock в роутер.\n\nПроверено настоящим SMTP-разговором: приём письма с вложением и cp1251, отказы (неизвестный получатель, ретрансляция, чужой домен для алиаса, нерезолвимый отправитель, AUTH, VRFY, SIZE), автоблокировка бота и снятие блокировки через интерфейс, STARTTLS до TLS 1.3, спам-порог (письмо на 10 очков ушло в «Спам»), песочница HTML.\n\nDNS настраивается вручную в reg.ru: MX resager.ru → mail.resager.ru, A mail.resager.ru → 45.129.196.26, SPF v=spf1 -all (мы не отправляем — жёсткая запись защищает домен от подделок) и DMARC p=reject.'
);
-- +goose StatementEnd

